argv:
$ErrorActionPreference='Stop'
$gh=Get-Command gh.exe -ErrorAction SilentlyContinue
Write-Output ('GH_CLI_AVAILABLE='+[bool]$gh)
if($gh){
 try{
  $p=& gh.exe api --method GET 'repos/foto6/WebAIBridge/actions/permissions' 2>$null|ConvertFrom-Json
  Write-Output ('GITHUB_ACTIONS_ENABLED='+$p.enabled)
  Write-Output ('GITHUB_ACTIONS_ALLOWED='+$p.allowed_actions)
  Write-Output ('GITHUB_SELECTED_ACTIONS_URL_SET='+[bool]$p.selected_actions_url)
 }catch{Write-Output 'GITHUB_ACTIONS_POLICY_UNAVAILABLE=True'}
}
Write-Output ('GITHUB_HOSTED_STEP_RUN_COUNT=0')
Write-Output ('RESULT_READ_ONLY=True')
